-- Control-plane schema. Timestamps are integer milliseconds since the Unix epoch.
-- IDs are "<prefix>_<ULID>" strings generated by src/lib/ids.ts.
-- Migration policy (docs/operations/upgrades.md): additive only; drops ship one minor release later.
-- Until the first release, this file is the whole schema: change it instead of adding a migration.

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'token_manager', 'access_manager', 'viewer')),
  status TEXT NOT NULL CHECK (status IN ('invited', 'pending', 'active', 'suspended')),
  invite_expires_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  last_login_at INTEGER,
  last_refused_at INTEGER,          -- last refused sign-in (not audited, like last_login_at)
  last_refused_subject TEXT         -- login subject of that attempt
);
CREATE INDEX users_status ON users (status);

-- I-OWNER-1: there is always at least one active owner once one exists.
-- Enforced in SQL so no code path (UI, manual SQL, concurrent requests) can bypass it.
CREATE TRIGGER users_last_owner_update
BEFORE UPDATE OF role, status ON users
WHEN OLD.role = 'owner' AND OLD.status = 'active'
  AND (NEW.role <> 'owner' OR NEW.status <> 'active')
  AND (SELECT count(*) FROM users WHERE role = 'owner' AND status = 'active') <= 1
BEGIN
  SELECT RAISE(ABORT, 'last_owner');
END;

CREATE TRIGGER users_last_owner_delete
BEFORE DELETE ON users
WHEN OLD.role = 'owner' AND OLD.status = 'active'
  AND (SELECT count(*) FROM users WHERE role = 'owner' AND status = 'active') <= 1
BEGIN
  SELECT RAISE(ABORT, 'last_owner');
END;

-- A login identity: (login provider, provider-specific stable subject) -> user.
CREATE TABLE user_identities (
  login_provider TEXT NOT NULL,
  subject TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  email TEXT,
  created_at INTEGER NOT NULL,
  last_used_at INTEGER,
  PRIMARY KEY (login_provider, subject)
);
CREATE INDEX user_identities_user ON user_identities (user_id);

-- Upstream APIs. The credential is sealed with AAD bound to (id, base_url, injection) (I-CRED-2).
CREATE TABLE credentials (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  base_url TEXT NOT NULL,
  injection TEXT NOT NULL,             -- canonical JSON Injection, see src/policy/validate.ts
  forward_headers TEXT NOT NULL DEFAULT '[]', -- JSON string[]
  timeout_ms INTEGER NOT NULL DEFAULT 120000,
  credential_sealed TEXT,              -- JSON, see src/crypto/envelope.ts
  credential_hint TEXT,
  credential_updated_at INTEGER,
  verify TEXT,                         -- JSON VerifyCheck or NULL
  -- The name was read from the verify check (the Slack bot name); a manual rename sets it to 0.
  name_from_check INTEGER NOT NULL DEFAULT 0 CHECK (name_from_check IN (0, 1)),
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  template_id TEXT                     -- service template: display and presets only, never in the AAD (ADR 0004)
);

-- Access rules (ADR 0026). One table, two kinds, fixed at insert:
-- * Credential access rule (credential_id set, id acr_<ULID>): lets workloads whose tokens `issuer`
--   signs, and that match `conditions`, use that one credential for `rules`. It carries its own
--   token verification settings, so every limit column is required.
-- * Global access rule (credential_id NULL, id gar_<ULID>): a ceiling on every credential access
--   rule with the same issuer_key. It never lets a request in by itself. A NULL limit column means
--   "no limit"; a non-NULL value is a limit. An empty JSON array is refused, so a malformed or empty
--   value never reads as "no limit" (I-AUTHZ-5). Disabled or expired rows still count as existing.
CREATE TABLE access_rules (
  id TEXT PRIMARY KEY,
  credential_id TEXT REFERENCES credentials (id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 100),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),  -- policy/validate-rules.ts DESCRIPTION_MAX_LENGTH
  -- A ProfileId (src/identity/profiles). Issuer profiles are code, not schema (ADR 0028): getProfile
  -- fails closed on an unknown one, and a new profile needs no migration.
  profile TEXT NOT NULL CHECK (length(profile) BETWEEN 1 AND 64),
  issuer TEXT NOT NULL CHECK (length(issuer) BETWEEN 1 AND 2048),  -- exact; jose compares it with iss
  -- Matching key of global rules: ASCII case and trailing slashes folded, so a ceiling can only reach
  -- more spellings of an issuer, never fewer. Written by the ops with issuerKey() (src/policy/limits.ts);
  -- the CHECK refuses any row where JS and SQL disagree. Decisions compare stored keys only (AR-3).
  issuer_key TEXT NOT NULL CHECK (issuer_key = lower(rtrim(issuer, '/'))),
  jwks_uri TEXT,
  audience TEXT CHECK (audience IS NULL OR length(audience) >= 16),
  allowed_algs TEXT,                    -- JSON string[]
  max_token_age_seconds INTEGER CHECK (max_token_age_seconds IS NULL OR max_token_age_seconds >= 60),
  tenant_pin TEXT,                      -- JSON Condition[] (exact, non-negated)
  anchor_claims TEXT,                   -- JSON string[]
  conditions TEXT,                      -- JSON Condition[]
  rules TEXT,                           -- JSON Rule[] (operations: methods + path)
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  expires_at INTEGER,
  created_by TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  CHECK ((credential_id IS NULL AND id GLOB 'gar_*') OR (credential_id IS NOT NULL AND id GLOB 'acr_*')),
  -- Credential access rule: every limit set, JSON well-formed (rows.ts still fails closed on bad rows).
  CHECK (credential_id IS NULL OR (
    jwks_uri IS NOT NULL AND audience IS NOT NULL AND max_token_age_seconds IS NOT NULL
    AND (CASE WHEN json_valid(allowed_algs)  THEN json_type(allowed_algs)  = 'array' AND json_array_length(allowed_algs) > 0 ELSE 0 END)
    AND (CASE WHEN json_valid(tenant_pin)    THEN json_type(tenant_pin)    = 'array' ELSE 0 END)
    AND (CASE WHEN json_valid(anchor_claims) THEN json_type(anchor_claims) = 'array' ELSE 0 END)
    AND (CASE WHEN json_valid(conditions)    THEN json_type(conditions)    = 'array' AND json_array_length(conditions) BETWEEN 1 AND 32 ELSE 0 END)
    AND (CASE WHEN json_valid(rules)         THEN json_type(rules)         = 'array' AND json_array_length(rules) BETWEEN 1 AND 50 ELSE 0 END))),
  -- Global access rule: NULL = no limit; a value must be a non-empty array.
  CHECK (credential_id IS NOT NULL OR (
    (allowed_algs  IS NULL OR (CASE WHEN json_valid(allowed_algs)  THEN json_type(allowed_algs)  = 'array' AND json_array_length(allowed_algs) > 0 ELSE 0 END))
    AND (tenant_pin    IS NULL OR (CASE WHEN json_valid(tenant_pin)    THEN json_type(tenant_pin)    = 'array' AND json_array_length(tenant_pin) > 0 ELSE 0 END))
    AND (anchor_claims IS NULL OR (CASE WHEN json_valid(anchor_claims) THEN json_type(anchor_claims) = 'array' AND json_array_length(anchor_claims) BETWEEN 1 AND 8 ELSE 0 END))
    AND (conditions    IS NULL OR (CASE WHEN json_valid(conditions)    THEN json_type(conditions)    = 'array' AND json_array_length(conditions) BETWEEN 1 AND 32 ELSE 0 END))
    AND (rules         IS NULL OR (CASE WHEN json_valid(rules)         THEN json_type(rules)         = 'array' AND json_array_length(rules) BETWEEN 1 AND 50 ELSE 0 END))))
);
-- Hot paths (a) and (b), admin lists and the foreign-key cascade from credentials: the rules of one
-- credential (at most 100), and the global rules of an issuer in every state (credential_id IS NULL,
-- issuer_key = ?; existence decides "not limited", AR-4). One full index: SQLite picks a partial index for (b) only
-- after ANALYZE, which local and test databases never run.
CREATE INDEX access_rules_credential ON access_rules (credential_id, issuer_key, created_at, id);
-- Hot path (c): unknown or disabled slug (I-TEN-1 order).
CREATE INDEX access_rules_issuer ON access_rules (issuer, created_at, id) WHERE enabled = 1;
-- Names are unique per credential, and among global rules. SQLite reports a violation as
-- "UNIQUE constraint failed: index 'access_rules_name'" (expression index).
CREATE UNIQUE INDEX access_rules_name ON access_rules (coalesce(credential_id, ''), name COLLATE NOCASE);

-- ADR 0014 integrity rules.
CREATE TRIGGER access_rules_id_fixed BEFORE UPDATE OF id ON access_rules
WHEN OLD.id IS NOT NEW.id BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;
-- The kind and the credential never change; a rule reaches another credential only by copy.
CREATE TRIGGER access_rules_credential_fixed BEFORE UPDATE OF credential_id ON access_rules
WHEN OLD.credential_id IS NOT NEW.credential_id BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;
CREATE TRIGGER access_rules_profile_fixed BEFORE UPDATE OF profile ON access_rules
WHEN OLD.profile IS NOT NEW.profile BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;
-- A ceiling never moves to another issuer (AR-5).
CREATE TRIGGER access_rules_global_issuer_fixed BEFORE UPDATE OF issuer ON access_rules
WHEN OLD.credential_id IS NULL AND OLD.issuer IS NOT NEW.issuer
BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;
-- Caps (AR-12), one error code each. NEW.issuer_key is safe to read: the CHECK ties it to NEW.issuer.
CREATE TRIGGER access_rules_credential_cap BEFORE INSERT ON access_rules
WHEN NEW.credential_id IS NOT NULL
  AND (SELECT count(*) FROM access_rules WHERE credential_id = NEW.credential_id) >= 100
BEGIN SELECT RAISE(ABORT, 'too_many_credential_rules'); END;
CREATE TRIGGER access_rules_global_cap BEFORE INSERT ON access_rules
WHEN NEW.credential_id IS NULL
  AND (SELECT count(*) FROM access_rules WHERE credential_id IS NULL
       AND issuer_key = NEW.issuer_key) >= 20
BEGIN SELECT RAISE(ABORT, 'too_many_global_rules'); END;
-- At most 4 distinct verification endpoints (jwks_uri, audience) per credential and issuer key (AR-10).
CREATE TRIGGER access_rules_verify_cap_insert BEFORE INSERT ON access_rules
WHEN NEW.credential_id IS NOT NULL
  AND (SELECT count(*) FROM (SELECT jwks_uri, audience FROM access_rules
         WHERE credential_id = NEW.credential_id AND issuer_key = NEW.issuer_key
       UNION SELECT NEW.jwks_uri, NEW.audience)) > 4
BEGIN SELECT RAISE(ABORT, 'too_many_verification_settings'); END;
CREATE TRIGGER access_rules_verify_cap_update BEFORE UPDATE OF jwks_uri, audience, issuer, issuer_key ON access_rules
WHEN NEW.credential_id IS NOT NULL
  AND (SELECT count(*) FROM (SELECT jwks_uri, audience FROM access_rules
         WHERE credential_id = NEW.credential_id AND issuer_key = NEW.issuer_key AND id <> NEW.id
       UNION SELECT NEW.jwks_uri, NEW.audience)) > 4
BEGIN SELECT RAISE(ABORT, 'too_many_verification_settings'); END;

-- Human labels for claim IDs, per access rule (ADR 0021, ADR 0026). Written only by access rule
-- saves. Display and form derivation only; src/policy/* never reads it. The ops check which claims a
-- profile labels and the shape of their IDs (ADR 0028).
CREATE TABLE claim_labels (
  access_rule_id TEXT NOT NULL REFERENCES access_rules (id) ON DELETE CASCADE,
  claim TEXT NOT NULL CHECK (length(claim) BETWEEN 1 AND 128),
  -- An ID: digits (GitHub, GitLab) or a prefixed opaque ID (Vercel `team_…`, `prj_…`).
  value TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 128 AND value NOT GLOB '*[^0-9A-Za-z_]*'),
  label TEXT NOT NULL CHECK (length(label) BETWEEN 1 AND 256),
  updated_at INTEGER NOT NULL,
  updated_by TEXT,
  PRIMARY KEY (access_rule_id, claim, value)
);

CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,                 -- JSON
  updated_at INTEGER NOT NULL,
  updated_by TEXT
);

CREATE TABLE audit_log (
  id TEXT PRIMARY KEY,
  ts INTEGER NOT NULL,
  actor_type TEXT NOT NULL CHECK (actor_type IN ('user', 'system')),
  actor_id TEXT,
  actor_email TEXT,
  action TEXT NOT NULL,                -- e.g. "service.create"
  target_type TEXT,
  target_id TEXT,
  summary TEXT NOT NULL,
  diff TEXT,                           -- JSON object, e.g. {before, after}; secrets redacted (I-CRED-1)
  ip TEXT,
  user_agent TEXT,
  -- svc_ ids of the credentials this row reveals (I-SCOPE-1); '["*"]' marks deployment-wide content
  resources TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(resources) AND json_type(resources) = 'array')
);
CREATE INDEX audit_log_ts ON audit_log (ts);
-- Audit list filters; the list orders by id. The target filter, the history of an object and its last
-- secret change match on target_id (target_type alone is only the settings and keyring filter).
CREATE INDEX audit_log_target ON audit_log (target_id, id);
CREATE INDEX audit_log_actor ON audit_log (actor_id, id);
CREATE INDEX audit_log_action ON audit_log (action, id);

-- Admin teams (ADR 0023). Not the Cloudflare Access team domain.
-- A team's scope is on credentials only. Levels: 0 none (the all-scope column only), 1 view,
-- 2 edit, 3 delete; each implies the lower ones. Flags (reveal, access_rules) each imply view.
-- The scope is "all" (credentials_all > 0, current and future credentials) or a list of rows in
-- team_credentials, never both (the *_one_mode triggers). The permission access_rules:global also
-- implies access_rules on every credential the member can view (src/db/authority.ts, scope.ts); a team
-- may hold it only with credentials_all >= 1 (the *_global_rules_scope triggers, D23).
CREATE TABLE teams (
  id TEXT PRIMARY KEY,
  builtin TEXT UNIQUE CHECK (builtin IN ('owner', 'admin', 'token_manager', 'access_manager', 'viewer')),
  name TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (length(trim(name)) BETWEEN 1 AND 64),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 280),
  credentials_all INTEGER NOT NULL DEFAULT 0 CHECK (credentials_all IN (0, 1, 2, 3)),
  credentials_all_reveal INTEGER NOT NULL DEFAULT 0 CHECK (credentials_all_reveal IN (0, 1)),
  credentials_all_access_rules INTEGER NOT NULL DEFAULT 0 CHECK (credentials_all_access_rules IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,         -- version: MAX(now, updated_at + 1) on every change to this team
  created_by TEXT,
  CHECK (credentials_all >= 1 OR (credentials_all_reveal = 0 AND credentials_all_access_rules = 0)),
  CHECK ((builtin IS NOT NULL AND id = 'tea_' || builtin)
      OR (builtin IS NULL AND length(id) = 30 AND id GLOB 'tea_[0-9A-HJKMNP-TV-Z]*'))
);

-- Only an active user's memberships count. Rows are only inserted or deleted.
CREATE TABLE team_members (
  team_id TEXT NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  added_at INTEGER NOT NULL,
  added_by TEXT,                       -- acting user id, or 'bootstrap', 'join' or 'break-glass'
  PRIMARY KEY (team_id, user_id)
) WITHOUT ROWID;
CREATE INDEX team_members_user ON team_members (user_id, team_id);

CREATE TABLE team_permissions (
  team_id TEXT NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
  permission TEXT NOT NULL CHECK (permission IN
    ('credentials:create', 'config:export', 'users:write', 'settings:write', 'keyring:rewrap',
     'access_rules:global')),
  PRIMARY KEY (team_id, permission)
) WITHOUT ROWID;

-- Explicit credential rows. Deleting a credential deletes its rows (foreign key).
CREATE TABLE team_credentials (
  team_id TEXT NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
  credential_id TEXT NOT NULL REFERENCES credentials (id) ON DELETE CASCADE,
  level INTEGER NOT NULL CHECK (level IN (1, 2, 3)),
  reveal INTEGER NOT NULL DEFAULT 0 CHECK (reveal IN (0, 1)),
  access_rules INTEGER NOT NULL DEFAULT 0 CHECK (access_rules IN (0, 1)),
  PRIMARY KEY (team_id, credential_id)
) WITHOUT ROWID;
CREATE INDEX team_credentials_credential ON team_credentials (credential_id);

-- The built-in teams (code mirror: BUILTIN_TEAMS in src/db/teams.ts). The seed runs before the
-- triggers below exist, because they refuse every change to a built-in team.
INSERT INTO teams (id, builtin, name, description, credentials_all, credentials_all_reveal,
                   credentials_all_access_rules, created_at, updated_at) VALUES
  ('tea_owner', 'owner', 'Owners',
   'Everything: people, teams, settings, keys, global access rules, and copying secrets.', 3, 1, 1, 0, 0),
  ('tea_admin', 'admin', 'Admins',
   'Every credential and its access rules, global access rules, and the export.', 3, 0, 1, 0, 0),
  ('tea_token_manager', 'token_manager', 'Credential managers',
   'Add, change and delete credentials. See every access rule.', 3, 0, 0, 0, 0),
  ('tea_access_manager', 'access_manager', 'Access managers',
   'Add, change and delete credential access rules. See every credential and global access rule.', 1, 0, 1, 0, 0),
  ('tea_viewer', 'viewer', 'Viewers',
   'See every credential and access rule. Change nothing.', 1, 0, 0, 0, 0);
INSERT INTO team_permissions (team_id, permission) VALUES
  ('tea_owner', 'credentials:create'), ('tea_owner', 'config:export'), ('tea_owner', 'users:write'),
  ('tea_owner', 'settings:write'), ('tea_owner', 'keyring:rewrap'), ('tea_owner', 'access_rules:global'),
  ('tea_admin', 'credentials:create'), ('tea_admin', 'config:export'), ('tea_admin', 'access_rules:global'),
  ('tea_token_manager', 'credentials:create');

-- I-RBAC-3: built-in teams are immutable. Their membership is not.
CREATE TRIGGER teams_builtin_insert BEFORE INSERT ON teams WHEN NEW.builtin IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;
CREATE TRIGGER teams_builtin_update BEFORE UPDATE ON teams WHEN OLD.builtin IS NOT NULL OR NEW.builtin IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;
CREATE TRIGGER teams_builtin_delete BEFORE DELETE ON teams WHEN OLD.builtin IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;

CREATE TRIGGER team_permissions_builtin_insert BEFORE INSERT ON team_permissions
WHEN EXISTS (SELECT 1 FROM teams WHERE id = NEW.team_id AND builtin IS NOT NULL)
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;
CREATE TRIGGER team_permissions_builtin_delete BEFORE DELETE ON team_permissions
WHEN EXISTS (SELECT 1 FROM teams WHERE id = OLD.team_id AND builtin IS NOT NULL)
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;
CREATE TRIGGER team_permissions_no_update BEFORE UPDATE ON team_permissions
BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;

-- Built-in teams never have explicit rows, so only the insert needs a trigger.
CREATE TRIGGER team_credentials_builtin_insert BEFORE INSERT ON team_credentials
WHEN EXISTS (SELECT 1 FROM teams WHERE id = NEW.team_id AND builtin IS NOT NULL)
BEGIN SELECT RAISE(ABORT, 'builtin_team'); END;
CREATE TRIGGER team_credentials_keys_fixed BEFORE UPDATE OF team_id, credential_id ON team_credentials
BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;
CREATE TRIGGER team_members_no_update BEFORE UPDATE ON team_members
BEGIN SELECT RAISE(ABORT, 'immutable_row'); END;

-- Scope mode: "all" (credentials_all > 0) or a list of rows, never both.
CREATE TRIGGER team_credentials_one_mode BEFORE INSERT ON team_credentials
WHEN EXISTS (SELECT 1 FROM teams WHERE id = NEW.team_id AND credentials_all <> 0)
BEGIN SELECT RAISE(ABORT, 'scope_mixed'); END;
CREATE TRIGGER teams_credentials_one_mode BEFORE UPDATE OF credentials_all ON teams
WHEN NEW.credentials_all <> 0 AND EXISTS (SELECT 1 FROM team_credentials WHERE team_id = NEW.id)
BEGIN SELECT RAISE(ABORT, 'scope_mixed'); END;

-- D23: access_rules:global only on a team with all-scope view, in both directions, so the implied
-- access_rules flag never combines one team's permission with another team's visibility.
CREATE TRIGGER team_permissions_global_rules_scope BEFORE INSERT ON team_permissions
WHEN NEW.permission = 'access_rules:global'
  AND NOT EXISTS (SELECT 1 FROM teams WHERE id = NEW.team_id AND credentials_all >= 1)
BEGIN SELECT RAISE(ABORT, 'global_rules_scope'); END;
CREATE TRIGGER teams_global_rules_scope BEFORE UPDATE OF credentials_all ON teams
WHEN NEW.credentials_all = 0
  AND EXISTS (SELECT 1 FROM team_permissions WHERE team_id = NEW.id AND permission = 'access_rules:global')
BEGIN SELECT RAISE(ABORT, 'global_rules_scope'); END;

-- I-OWNER-1: once an active Owners member exists, one always exists. The condition is "no OTHER
-- active owner", so it holds in any order the foreign-key cascades run in.
CREATE TRIGGER team_members_last_owner_delete BEFORE DELETE ON team_members
WHEN OLD.team_id = 'tea_owner'
  AND EXISTS (SELECT 1 FROM users WHERE id = OLD.user_id AND status = 'active')
  AND NOT EXISTS (SELECT 1 FROM team_members m JOIN users u ON u.id = m.user_id
                  WHERE m.team_id = 'tea_owner' AND m.user_id <> OLD.user_id AND u.status = 'active')
BEGIN SELECT RAISE(ABORT, 'last_owner'); END;

-- I-LINK-1: the default team is join-safe in both directions, and it cannot be deleted.
-- putSettingStatement is INSERT ... ON CONFLICT DO UPDATE. SQLite fires the INSERT trigger first
-- and, on a conflict, the UPDATE trigger, so both triggers are necessary. Malformed JSON makes
-- json_extract raise, which also refuses the write.
CREATE TRIGGER settings_join_team_insert BEFORE INSERT ON settings
WHEN NEW.key = 'join_team' AND NOT EXISTS (
  SELECT 1 FROM teams t
  WHERE t.id = json_extract(NEW.value, '$') AND t.id <> 'tea_owner' AND t.credentials_all_reveal = 0
    AND NOT EXISTS (SELECT 1 FROM team_permissions p WHERE p.team_id = t.id
                    AND p.permission IN ('users:write', 'settings:write', 'keyring:rewrap'))
    AND NOT EXISTS (SELECT 1 FROM team_credentials x WHERE x.team_id = t.id AND x.reveal = 1))
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;
CREATE TRIGGER settings_join_team_update BEFORE UPDATE OF value ON settings
WHEN NEW.key = 'join_team' AND NOT EXISTS (
  SELECT 1 FROM teams t
  WHERE t.id = json_extract(NEW.value, '$') AND t.id <> 'tea_owner' AND t.credentials_all_reveal = 0
    AND NOT EXISTS (SELECT 1 FROM team_permissions p WHERE p.team_id = t.id
                    AND p.permission IN ('users:write', 'settings:write', 'keyring:rewrap'))
    AND NOT EXISTS (SELECT 1 FROM team_credentials x WHERE x.team_id = t.id AND x.reveal = 1))
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;

CREATE TRIGGER teams_default_delete BEFORE DELETE ON teams
WHEN EXISTS (SELECT 1 FROM settings WHERE key = 'join_team' AND json_extract(value, '$') = OLD.id)
BEGIN SELECT RAISE(ABORT, 'default_team'); END;
CREATE TRIGGER team_permissions_default_safe BEFORE INSERT ON team_permissions
WHEN NEW.permission IN ('users:write', 'settings:write', 'keyring:rewrap')
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'join_team' AND json_extract(value, '$') = NEW.team_id)
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;
CREATE TRIGGER teams_default_reveal BEFORE UPDATE OF credentials_all_reveal ON teams
WHEN NEW.credentials_all_reveal = 1
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'join_team' AND json_extract(value, '$') = NEW.id)
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;
CREATE TRIGGER team_credentials_default_reveal_insert BEFORE INSERT ON team_credentials
WHEN NEW.reveal = 1
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'join_team' AND json_extract(value, '$') = NEW.team_id)
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;
CREATE TRIGGER team_credentials_default_reveal_update BEFORE UPDATE OF reveal ON team_credentials
WHEN NEW.reveal = 1
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'join_team' AND json_extract(value, '$') = NEW.team_id)
BEGIN SELECT RAISE(ABORT, 'join_team_unsafe'); END;
